class Customer {
  + address : string
  + vatNumber : string
  + headOfficeAddress : string
}

class Product {
  + name : string
  + stock : int
}

class Order {
  + orderDate : date
  + paymentDate : date
  + shippingDate : date
  + isPaid : boolean
  + isShipped : boolean
}

class OrderLine {
  + quantity : int
  + isShipped : boolean
}

class Warehouse {
  + address : string
}

class Invoice {
}

class Shipment {
  + status : string
}

class ShipmentLine {
}

class Delivery {
  + status : string
}

Customer "1" -- "*" Order : places
Customer "1" -- "*" Warehouse : has
Order "1" *-- "1..*" OrderLine
OrderLine "1" -- "1" Product : contains
Order "1" -- "0..1" Invoice : generates
Order "1" -- "0..*" Shipment : grouped into
Shipment "1" *-- "1..*" ShipmentLine
ShipmentLine "1" -- "1" OrderLine : includes
Shipment "1" -- "0..*" Delivery : contains
Delivery "1" -- "1..*" ShipmentLine : delivers

@enduml

